insert into public.trilhas (id, slug, titulo, descricao, categoria, ordem) values ('orcamento-pessoal', 'orcamento-pessoal', 'Orçamento Pessoal', 'Organize o seu dinheiro e monte a sua reserva.', 'Organização', 1)
insert into public.trilhas (id, slug, titulo, descricao, categoria, ordem) values ('juros-compostos', 'juros-compostos', 'Juros Compostos', 'Juros sobre juros: faça o tempo trabalhar por você.', 'Investimentos', 2)
insert into public.trilhas (id, slug, titulo, descricao, categoria, ordem) values ('cartao-de-credito', 'cartao-de-credito', 'Cartão de Crédito', 'Use o cartão sem cair no rotativo.', 'Crédito', 3)
insert into public.trilhas (id, slug, titulo, descricao, categoria, ordem) values ('inflacao-e-investimentos', 'inflacao-e-investimentos', 'Inflação e Investimentos', 'Proteja o seu poder de compra e diversifique.', 'Investimentos', 4)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('orcamento-pessoal-1', 'orcamento-pessoal', 1, 'Para onde vai o seu dinheiro', '[{"tipo":"texto","texto":"Orçamento é o plano de quanto dinheiro entra e para onde ele vai. O primeiro passo é conhecer a sua renda, que é todo o dinheiro que você recebe no mês: salário, bolsa, trabalhos extras."},{"tipo":"texto","texto":"Os gastos se dividem em dois grupos. Gastos fixos se repetem com o mesmo valor, como aluguel, internet e mensalidades. Gastos variáveis mudam de mês para mês, como transporte, alimentação fora de casa e lazer."},{"tipo":"texto","texto":"Para descobrir os seus números, anote cada gasto por um mês, mesmo os pequenos. Pode ser no caderno, numa planilha ou no celular. No fim do mês, some tudo e compare com a sua renda."},{"tipo":"texto","texto":"Se sobrar dinheiro, ele pode virar reserva ou ajudar numa meta. Se faltar, a anotação mostra onde dá para cortar."},{"tipo":"exemplo","titulo":"Renda de R$ 1.800,00 em um mês","linhas":["Gastos fixos: R$ 1.050,00.","Gastos variáveis: R$ 600,00.","Total de gastos: R$ 1.650,00.","Sobram R$ 150,00 (R$ 1.800,00 − R$ 1.650,00)."]},{"tipo":"resumo","itens":["Renda é tudo o que você recebe no mês.","Gastos fixos se repetem; gastos variáveis mudam.","Anotar os gastos por um mês mostra para onde o dinheiro vai."]}]'::jsonb, 4)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('orcamento-pessoal-2', 'orcamento-pessoal', 2, 'Montando o seu orçamento', '[{"tipo":"texto","texto":"Montar o orçamento é decidir, antes de gastar, o que fazer com cada parte da renda. Comece listando as suas metas, como trocar de celular, fazer uma viagem ou formar uma reserva, e ordene por prioridade."},{"tipo":"texto","texto":"Uma divisão muito usada como ponto de partida é a 50/30/20: 50% da renda para necessidades (moradia, comida, transporte), 30% para desejos (lazer, compras) e 20% para guardar."},{"tipo":"texto","texto":"Ela é uma sugestão, não uma lei. Se o seu aluguel pesa mais, ajuste os percentuais, mas mantenha sempre uma parte para guardar."},{"tipo":"texto","texto":"Revise o orçamento todo mês. A vida muda, e o plano precisa acompanhar."},{"tipo":"exemplo","titulo":"Renda de R$ 2.000,00 na divisão 50/30/20","linhas":["Necessidades (50%): R$ 1.000,00.","Desejos (30%): R$ 600,00.","Guardar (20%): R$ 400,00."]},{"tipo":"resumo","itens":["Defina metas e ordene por prioridade.","A divisão 50/30/20 é um ponto de partida e pode ser ajustada.","Guardar uma parte da renda deve entrar no plano desde o começo.","Revise o orçamento todo mês."]}]'::jsonb, 4)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('orcamento-pessoal-3', 'orcamento-pessoal', 3, 'Reserva de emergência', '[{"tipo":"texto","texto":"Reserva de emergência é um dinheiro guardado para imprevistos, como um conserto urgente, uma despesa de saúde ou a perda de renda. Ela evita que você precise pegar dinheiro emprestado, com juros altos, na hora do aperto."},{"tipo":"texto","texto":"Uma meta comum é guardar de 3 a 6 meses dos seus gastos essenciais, que são os de que você não abre mão: moradia, comida, transporte e contas básicas."},{"tipo":"texto","texto":"Onde guardar? Escolha aplicações de baixo risco e com liquidez, que é a facilidade de transformar a aplicação em dinheiro rapidamente. O objetivo da reserva é estar disponível quando você precisar, não render muito."},{"tipo":"texto","texto":"Comece pequeno e guarde um valor fixo todo mês, de preferência assim que receber."},{"tipo":"exemplo","titulo":"Gastos essenciais de R$ 1.200,00 por mês","linhas":["Meta mínima (3 meses): R$ 3.600,00.","Meta máxima (6 meses): R$ 7.200,00.","Guardando R$ 200,00 por mês, a meta mínima chega em 18 meses, sem contar o rendimento."]},{"tipo":"resumo","itens":["A reserva serve para imprevistos e evita dívidas caras.","A meta é de 3 a 6 meses de gastos essenciais.","Guarde em aplicações de baixo risco e com liquidez."]}]'::jsonb, 4)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('juros-compostos-1', 'juros-compostos', 1, 'Juros simples e juros compostos', '[{"tipo":"texto","texto":"Juros são o \"aluguel\" do dinheiro: quem empresta recebe, quem pega emprestado paga. Quando você guarda dinheiro numa aplicação, é você quem recebe os juros."},{"tipo":"texto","texto":"Nos juros simples, a taxa incide sempre sobre o valor inicial. Nos juros compostos, ela incide sobre o saldo de cada mês, que já inclui os juros dos meses anteriores: são os \"juros sobre juros\"."},{"tipo":"texto","texto":"No começo a diferença é pequena, mas ela cresce com o tempo. Por isso os juros compostos ajudam quem investe e pesam para quem está devendo."},{"tipo":"exemplo","titulo":"R$ 1.000,00 a 1% ao mês por 3 meses","linhas":["Juros simples: R$ 10,00 por mês, e você termina com R$ 1.030,00.","Juros compostos: R$ 1.010,00, depois R$ 1.020,10 e, no fim, R$ 1.030,30.","A diferença ainda é de R$ 0,30, mas aumenta a cada mês."]},{"tipo":"resumo","itens":["Juros compostos rendem sobre o saldo, não só sobre o valor inicial.","A diferença para os juros simples cresce com o tempo.","Juros sobre juros ajudam quem investe e pesam para quem deve."]}]'::jsonb, 4)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('juros-compostos-2', 'juros-compostos', 2, 'O tempo a seu favor', '[{"tipo":"texto","texto":"Aporte é o dinheiro que você acrescenta à aplicação de tempos em tempos, por exemplo todo mês. Os juros compostos funcionam melhor com aportes regulares e, principalmente, com tempo."},{"tipo":"texto","texto":"Quanto mais cedo você começa, mais meses de juros sobre juros o seu dinheiro acumula. Esperar para começar pode custar mais do que parece."},{"tipo":"texto","texto":"O valor que você terá no fim do prazo se chama montante: é o que você investiu somado aos juros recebidos. Os simuladores do app calculam o montante para você."},{"tipo":"exemplo","titulo":"R$ 100,00 por mês a 1% ao mês, com aporte no fim de cada mês","linhas":["Em 12 meses: R$ 1.268,25 (você colocou R$ 1.200,00).","Em 60 meses: R$ 8.166,97 (você colocou R$ 6.000,00).","Os juros somam R$ 2.166,97, e crescem mais rápido a cada ano."]},{"tipo":"resumo","itens":["Aporte é o dinheiro que você acrescenta à aplicação.","Montante é o valor final: o que foi investido mais os juros.","Começar cedo e aportar com regularidade faz o tempo trabalhar a seu favor."]}]'::jsonb, 4)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('juros-compostos-3', 'juros-compostos', 3, 'Taxa ao mês e taxa ao ano', '[{"tipo":"texto","texto":"Taxas aparecem ao mês ou ao ano, e não dá para compará-las sem converter. Como os juros são compostos, 1% ao mês não equivale a 12% ao ano: equivale a cerca de 12,68% ao ano."},{"tipo":"texto","texto":"Por isso não se divide a taxa anual por 12 para achar a taxa mensal. O cálculo correto é a equivalência: a taxa mensal é aquela que, composta por 12 meses, resulta na taxa anual."},{"tipo":"texto","texto":"O CDI é a taxa de referência dos investimentos de renda fixa, aqueles em que as regras de rendimento são conhecidas na hora da aplicação. Ele é divulgado ao ano; para comparar com uma taxa mensal, converta pela equivalência."},{"tipo":"exemplo","titulo":"Equivalência entre taxa ao mês e ao ano","linhas":["1% ao mês equivale a 12,68% ao ano, não a 12%.","10% ao ano equivalem a 0,80% ao mês, não a 0,83% (que seria 10 ÷ 12).","Os simuladores do app fazem a conversão desse jeito."]},{"tipo":"resumo","itens":["Taxa ao mês e taxa ao ano precisam ser convertidas por equivalência.","Nunca divida a taxa anual por 12.","O CDI é uma referência anual da renda fixa."]}]'::jsonb, 5)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('cartao-de-credito-1', 'cartao-de-credito', 1, 'Como funciona a fatura', '[{"tipo":"texto","texto":"A fatura do cartão reúne as compras de um período e mostra quanto você deve pagar. O limite é o valor máximo que o banco libera para você gastar no cartão."},{"tipo":"texto","texto":"O fechamento é o dia em que a fatura \"vira\": compras feitas depois dele entram na fatura seguinte. O vencimento é a data-limite para pagar."},{"tipo":"texto","texto":"Pagar o valor total até o vencimento evita juros. Nesse caso, o cartão é só uma conveniência, e não um crédito caro."},{"tipo":"texto","texto":"Antes de comprar no cartão, pergunte-se: \"eu consigo pagar a fatura inteira?\". Se a resposta for não, a compra pode custar bem mais do que o preço."},{"tipo":"exemplo","titulo":"Compras de R$ 800,00 até o fechamento","linhas":["Fatura: R$ 800,00.","Pagando R$ 800,00 no vencimento, os juros são R$ 0,00.","Pagando menos, o restante vira dívida com juros (veja a próxima lição)."]},{"tipo":"resumo","itens":["A fatura soma as compras do período; o limite é o teto de gastos.","O fechamento define em qual fatura a compra entra.","Pagar o total até o vencimento evita juros."]}]'::jsonb, 4)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('cartao-de-credito-2', 'cartao-de-credito', 2, 'Mínimo e rotativo', '[{"tipo":"texto","texto":"O pagamento mínimo é o menor valor que você pode pagar para manter a fatura em dia. Pagar só o mínimo parece um alívio, mas o que sobrou continua sendo dívida."},{"tipo":"texto","texto":"O saldo que não foi pago entra no crédito rotativo, uma das modalidades de crédito com juros mais altos do mercado. Pelas regras atuais, o rotativo dura só até a próxima fatura: depois disso, o saldo precisa ser parcelado."},{"tipo":"texto","texto":"Os juros do rotativo incidem sobre o saldo que ficou em aberto, e a taxa costuma ser de vários por cento ao mês. Em pouco tempo, a dívida cresce bem mais do que a compra original."},{"tipo":"exemplo","titulo":"Fatura de R$ 1.000,00 e pagamento mínimo de R$ 150,00","linhas":["Saldo que vai para o rotativo: R$ 850,00.","Com juros de 15% ao mês (um valor de exemplo), o saldo vira R$ 977,50 na fatura seguinte.","Foram R$ 127,50 de juros em apenas um mês."]},{"tipo":"resumo","itens":["Pagar só o mínimo deixa o resto da fatura como dívida.","O rotativo tem juros altos e dura só até a próxima fatura.","Sempre que possível, pague o valor total."]}]'::jsonb, 4)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('cartao-de-credito-3', 'cartao-de-credito', 3, 'Parcelamento e teto dos juros', '[{"tipo":"texto","texto":"Depois do rotativo, o saldo da fatura é parcelado em parcelas iguais. No cálculo conhecido como tabela Price, todas as parcelas têm o mesmo valor, e os juros incidem sobre o saldo que ainda falta pagar."},{"tipo":"texto","texto":"O CET, custo efetivo total, reúne os juros, as tarifas e os impostos de uma operação de crédito. Ao comparar ofertas, olhe o CET, e não só a taxa de juros anunciada."},{"tipo":"texto","texto":"A lei limita a cobrança: a soma dos juros do rotativo e do parcelamento não pode passar de 100% do valor que ficou em aberto (Lei nº 14.690/2023). Na prática, você nunca paga mais do que o dobro desse valor."},{"tipo":"exemplo","titulo":"R$ 977,50 em 12 parcelas a 9% ao mês","linhas":["Cada parcela: R$ 136,51.","Total pago nas parcelas: cerca de R$ 1.638,00.","Juros: cerca de R$ 788,00, sobre os R$ 850,00 que ficaram em aberto."]},{"tipo":"resumo","itens":["O saldo do rotativo é parcelado em parcelas iguais (tabela Price).","O CET mostra o custo total de uma operação de crédito.","A lei limita os juros a 100% do valor que ficou em aberto."]}]'::jsonb, 5)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('inflacao-e-investimentos-1', 'inflacao-e-investimentos', 1, 'O que é inflação', '[{"tipo":"texto","texto":"Inflação é o aumento geral e contínuo dos preços. Com o tempo, a mesma quantia de dinheiro compra menos coisas: é o que chamamos de perda do poder de compra."},{"tipo":"texto","texto":"No Brasil, a inflação oficial é medida pelo IPCA, o Índice Nacional de Preços ao Consumidor Amplo, calculado pelo IBGE. Ele acompanha os preços de uma cesta de produtos e serviços que as famílias consomem."},{"tipo":"texto","texto":"Por isso o dinheiro parado perde valor: se os preços sobem e o seu dinheiro não rende, você compra menos. Investir ajuda a proteger o poder de compra."},{"tipo":"exemplo","titulo":"Compras de R$ 500,00 com inflação de 5% ao ano","linhas":["Hoje, as compras custam R$ 500,00.","Um ano depois, as mesmas compras passam a custar R$ 525,00.","Quem deixou o dinheiro parado consegue comprar menos."]},{"tipo":"resumo","itens":["Inflação é o aumento geral dos preços.","O IPCA, medido pelo IBGE, é o índice oficial de inflação.","Dinheiro parado perde poder de compra."]}]'::jsonb, 4)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('inflacao-e-investimentos-2', 'inflacao-e-investimentos', 2, 'Rendimento real', '[{"tipo":"texto","texto":"O rendimento nominal é o que a aplicação rende no papel. O rendimento real desconta a inflação e mostra quanto o seu poder de compra realmente cresceu, ou diminuiu."},{"tipo":"texto","texto":"Uma conta aproximada é: ganho real ≈ rendimento − inflação. A conta exata é (1 + rendimento) ÷ (1 + inflação) − 1."},{"tipo":"texto","texto":"Quando a aplicação rende menos que a inflação, o ganho real é negativo: o saldo até aumenta, mas dá para comprar menos do que antes."},{"tipo":"exemplo","titulo":"Rendimento nominal contra inflação de 5% ao ano","linhas":["Aplicação de 8% ao ano: ganho real de cerca de 2,86% ao ano.","Aplicação de 3% ao ano: o poder de compra cai cerca de 1,9% ao ano."]},{"tipo":"resumo","itens":["Rendimento real é o rendimento descontada a inflação.","A conta exata é (1 + rendimento) ÷ (1 + inflação) − 1.","Render menos que a inflação significa perder poder de compra."]}]'::jsonb, 4)
insert into public.licoes (id, trilha_id, ordem, titulo, conteudo, tempo_leitura_min) values ('inflacao-e-investimentos-3', 'inflacao-e-investimentos', 3, 'Diversificação', '[{"tipo":"texto","texto":"Ativo é qualquer bem ou aplicação que pode gerar renda ou valorização, como ações, títulos e imóveis. Todo ativo tem risco, que é a chance de o resultado ser diferente do esperado, inclusive com perda de dinheiro."},{"tipo":"texto","texto":"Diversificar é dividir o dinheiro entre ativos diferentes, para que a queda de um não derrube tudo. É a ideia por trás do ditado de não colocar todos os ovos na mesma cesta."},{"tipo":"texto","texto":"Fundos de investimento reúnem o dinheiro de muitas pessoas para comprar vários ativos, e são um jeito simples de diversificar. A diversificação reduz o risco, mas não o elimina: todo investimento pode ter perdas."},{"tipo":"exemplo","titulo":"R$ 1.000,00 em uma ação ou divididos em cinco","linhas":["Numa única ação que cai 30%, os R$ 1.000,00 viram R$ 700,00.","Divididos em 5 partes de R$ 200,00, se só uma cair 30%, o total fica em R$ 940,00.","A perda cai de R$ 300,00 para R$ 60,00."]},{"tipo":"resumo","itens":["Ativo é um bem ou aplicação que pode gerar renda; todo ativo tem risco.","Diversificar é não concentrar tudo num único ativo.","Fundos reúnem vários ativos, mas nenhum investimento é livre de perdas."]}]'::jsonb, 4)
