insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-f1', 'orcamento-pessoal-1-quiz', 'No orçamento pessoal, o que é a renda?', array['Todo o dinheiro que você recebe no mês', 'Só o dinheiro que sobra depois dos gastos', 'O total das suas dívidas', 'O valor guardado na reserva de emergência']::text[], 0, 'facil', 'Renda é tudo o que entra no mês, como salário, bolsa e trabalhos extras. O que sobra depois dos gastos é o saldo do mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m1', 'orcamento-pessoal-1-quiz', 'Marina recebe R$ 2.500,00 por mês. Os gastos fixos somam R$ 1.300,00 e os variáveis, R$ 900,00. Quanto sobra no mês?', array['R$ 200,00', 'R$ 300,00', 'R$ 1.200,00', 'R$ 600,00']::text[], 1, 'medio', 'Os gastos somam R$ 1.300,00 + R$ 900,00 = R$ 2.200,00. Sobram R$ 2.500,00 − R$ 2.200,00 = R$ 300,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m2', 'orcamento-pessoal-1-quiz', 'Qual destes gastos é um gasto variável?', array['Aluguel, com o mesmo valor todo mês', 'Mensalidade da escola', 'Lanches e passeios, que mudam de mês para mês', 'Parcela fixa do celular']::text[], 2, 'medio', 'Gastos variáveis mudam de valor ou de frequência conforme o mês. Aluguel, mensalidade e parcela fixa se repetem com o mesmo valor, por isso são gastos fixos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m3', 'orcamento-pessoal-1-quiz', 'Lucas gasta R$ 15,00 por dia útil em lanches. Em um mês com 20 dias úteis, quanto isso soma?', array['R$ 150,00', 'R$ 450,00', 'R$ 600,00', 'R$ 300,00']::text[], 3, 'medio', 'Basta multiplicar: R$ 15,00 × 20 = R$ 300,00. Anotar os gastos pequenos mostra o quanto eles pesam no fim do mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-f1', 'orcamento-pessoal-2-quiz', 'Na divisão 50/30/20 do orçamento, o que representa a parte de 20%?', array['As necessidades, como moradia e comida', 'Os desejos, como lazer e compras', 'O que você separa para guardar', 'Os impostos do mês']::text[], 2, 'facil', 'Na divisão 50/30/20, 50% da renda vão para as necessidades, 30% para os desejos e 20% para guardar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m1', 'orcamento-pessoal-2-quiz', 'Com renda de R$ 3.000,00 e a divisão 50/30/20, quanto vai para as necessidades?', array['R$ 600,00', 'R$ 900,00', 'R$ 1.000,00', 'R$ 1.500,00']::text[], 3, 'medio', 'As necessidades ficam com 50% da renda: R$ 3.000,00 × 0,50 = R$ 1.500,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m2', 'orcamento-pessoal-2-quiz', 'Com renda de R$ 1.500,00 e a divisão 50/30/20, quanto deve ser guardado por mês?', array['R$ 300,00', 'R$ 150,00', 'R$ 450,00', 'R$ 750,00']::text[], 0, 'medio', 'Guardar corresponde a 20% da renda: R$ 1.500,00 × 0,20 = R$ 300,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-d1', 'orcamento-pessoal-2-quiz', 'Ana ganha R$ 2.400,00 e suas necessidades já consomem R$ 1.500,00. Se ela mantiver os 20% para guardar, quanto sobra para os desejos?', array['R$ 720,00', 'R$ 420,00', 'R$ 900,00', 'R$ 480,00']::text[], 1, 'dificil', 'Guardar 20% de R$ 2.400,00 dá R$ 480,00. Restam R$ 2.400,00 − R$ 1.500,00 − R$ 480,00 = R$ 420,00 para os desejos. Os percentuais podem ser ajustados, mas a parte de guardar fica.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-f1', 'orcamento-pessoal-3-quiz', 'Para que serve a reserva de emergência?', array['Para pagar compras de lazer', 'Para cobrir imprevistos sem precisar de dívidas caras', 'Para investir em ativos de alto risco', 'Para quitar a fatura do cartão todo mês']::text[], 1, 'facil', 'A reserva existe para imprevistos, como um conserto urgente ou a perda de renda, e evita que você pegue dinheiro emprestado com juros altos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m1', 'orcamento-pessoal-3-quiz', 'Os gastos essenciais de uma pessoa são R$ 2.000,00 por mês. Qual é a meta mínima da reserva, de 3 meses de gastos?', array['R$ 2.000,00', 'R$ 4.000,00', 'R$ 6.000,00', 'R$ 12.000,00']::text[], 2, 'medio', 'A meta mínima é de 3 meses de gastos essenciais: R$ 2.000,00 × 3 = R$ 6.000,00. Seis meses seriam R$ 12.000,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-d1', 'orcamento-pessoal-3-quiz', 'Pedro tem gastos essenciais de R$ 1.500,00 e quer uma reserva de 6 meses. Guardando R$ 450,00 por mês, sem contar rendimento, em quantos meses ele chega à meta?', array['15 meses', '18 meses', '24 meses', '20 meses']::text[], 3, 'dificil', 'A meta é 6 × R$ 1.500,00 = R$ 9.000,00. Dividindo pelo valor guardado por mês: R$ 9.000,00 ÷ R$ 450,00 = 20 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-d2', 'orcamento-pessoal-3-quiz', 'Uma aplicação rende bem, mas só libera o dinheiro depois de 2 anos. Por que ela é uma má escolha para a reserva de emergência?', array['Falta liquidez: o dinheiro não estaria disponível no imprevisto', 'Porque rende mais do que a inflação', 'Porque exige aportes todo mês', 'Porque o risco de perder o dinheiro é sempre zero']::text[], 0, 'dificil', 'A reserva precisa estar disponível quando o imprevisto aparecer. A liquidez, que é a facilidade de transformar a aplicação em dinheiro, importa mais do que o rendimento.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-f1', 'juros-compostos-1-quiz', 'O que são juros compostos?', array['Juros calculados só sobre o valor inicial', 'Juros calculados sobre o saldo, incluindo os juros já acumulados', 'Uma taxa cobrada uma única vez, no começo', 'Juros que diminuem a cada mês']::text[], 1, 'facil', 'Nos juros compostos, a taxa incide sobre o saldo de cada mês, que já inclui os juros anteriores. É o chamado "juros sobre juros".', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m1', 'juros-compostos-1-quiz', 'R$ 2.000,00 rendem a juros simples de 1% ao mês por 3 meses. Quanto você tem no final?', array['R$ 2.030,00', 'R$ 2.060,60', 'R$ 2.060,00', 'R$ 2.600,00']::text[], 2, 'medio', 'Nos juros simples, os juros são sempre 1% de R$ 2.000,00 = R$ 20,00 por mês. Em 3 meses, são R$ 60,00 de juros, e o total é R$ 2.060,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m2', 'juros-compostos-1-quiz', 'Duas aplicações de R$ 1.000,00 rendem 2% ao mês por 10 meses: uma com juros simples e outra com juros compostos. Qual termina com mais dinheiro?', array['A de juros simples', 'As duas terminam com o mesmo valor', 'Depende do mês em que começaram', 'A de juros compostos']::text[], 3, 'medio', 'Com juros simples, o total é R$ 1.200,00. Com juros compostos, R$ 1.000,00 × 1,02^10 ≈ R$ 1.218,99. Os juros sobre juros fazem a diferença.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m3', 'juros-compostos-1-quiz', 'Com juros compostos de 10% ao mês, quanto R$ 1.000,00 viram depois de 2 meses?', array['R$ 1.210,00', 'R$ 1.100,00', 'R$ 1.200,00', 'R$ 1.220,00']::text[], 0, 'medio', 'No 1º mês: R$ 1.000,00 × 1,10 = R$ 1.100,00. No 2º mês, os juros incidem sobre R$ 1.100,00: R$ 1.100,00 × 1,10 = R$ 1.210,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-f1', 'juros-compostos-2-quiz', 'O que é o montante de uma aplicação?', array['O valor final: o que foi investido mais os juros', 'Só o valor investido no começo', 'Só o total de juros recebidos', 'A taxa de juros anual']::text[], 0, 'facil', 'Montante é o valor que você terá no fim do prazo: o dinheiro investido somado aos juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m1', 'juros-compostos-2-quiz', 'Você guarda R$ 100,00 por mês numa aplicação que rende 1% ao mês. Depois de 12 meses, o saldo fica mais perto de qual valor?', array['R$ 1.200,00', 'R$ 1.268,25', 'R$ 1.320,00', 'R$ 1.100,00']::text[], 1, 'medio', 'Cada aporte rende juros sobre juros a partir do mês em que entra. Por isso o saldo passa dos R$ 1.200,00 aportados e chega a R$ 1.268,25.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m2', 'juros-compostos-2-quiz', 'Duas pessoas fazem aportes mensais iguais, à mesma taxa, até o mesmo dia. Uma começou 5 anos antes da outra. Quem termina com o maior montante?', array['Quem começou depois', 'Os dois terminam com o mesmo montante', 'Quem começou antes, porque os seus aportes rendem por mais meses', 'Não dá para saber sem conhecer a taxa']::text[], 2, 'medio', 'Quem começa antes faz mais aportes e deixa cada aporte render por mais tempo. O tempo é um dos maiores aliados dos juros compostos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-d1', 'juros-compostos-2-quiz', 'Você aplica R$ 100,00 por mês durante 60 meses e chega a R$ 8.166,97 de montante. Quanto desse valor são juros?', array['R$ 8.166,97', 'R$ 6.000,00', 'R$ 1.166,97', 'R$ 2.166,97']::text[], 3, 'dificil', 'Você investiu R$ 100,00 × 60 = R$ 6.000,00. Os juros são o montante menos o que foi investido: R$ 8.166,97 − R$ 6.000,00 = R$ 2.166,97.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-f1', 'juros-compostos-3-quiz', 'O que é o CDI?', array['Um imposto sobre investimentos', 'Um tipo de cartão de crédito', 'A taxa de referência dos investimentos de renda fixa', 'O valor mínimo para começar a investir']::text[], 2, 'facil', 'O CDI é a taxa de referência da renda fixa no Brasil. Ele é divulgado ao ano e serve de base para comparar rendimentos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m1', 'juros-compostos-3-quiz', 'Uma aplicação rende 1% ao mês. A taxa equivalente ao ano é, aproximadamente:', array['12,00% ao ano', '10,00% ao ano', '13,50% ao ano', '12,68% ao ano']::text[], 3, 'medio', '(1 + 0,01)^12 − 1 ≈ 0,1268, ou seja, 12,68% ao ano. Multiplicar por 12 ignora os juros sobre juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-d1', 'juros-compostos-3-quiz', 'Uma aplicação rende 12% ao ano. Qual é a taxa mensal equivalente?', array['Exatamente 1% ao mês', 'Cerca de 0,95% ao mês', 'Cerca de 1,2% ao mês', 'Exatamente 12% ao mês']::text[], 1, 'dificil', 'Dividir por 12 ignora os juros sobre juros. Pela equivalência, (1 + 0,12)^(1/12) − 1 ≈ 0,95% ao mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-d2', 'juros-compostos-3-quiz', 'Uma aplicação rende 2% ao mês. Qual é, aproximadamente, a taxa equivalente ao ano?', array['Cerca de 26,82% ao ano', 'Exatamente 24% ao ano', 'Cerca de 2,4% ao ano', 'Cerca de 28% ao ano']::text[], 0, 'dificil', 'Multiplicar 2% por 12 dá 24%, mas isso ignora os juros sobre juros. Pela equivalência, (1,02)^12 − 1 ≈ 26,82% ao ano.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-f1', 'cartao-de-credito-1-quiz', 'O que é o fechamento da fatura do cartão?', array['A data-limite para pagar a fatura', 'O cancelamento do cartão', 'O valor máximo que o banco libera para gastar', 'O dia em que a fatura "vira": compras feitas depois entram na fatura seguinte']::text[], 3, 'facil', 'No fechamento, a fatura é encerrada com as compras feitas até aquele dia. O vencimento é outra data: o último dia para pagar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m1', 'cartao-de-credito-1-quiz', 'Roberto fez compras de R$ 450,00 antes do fechamento e pagou os R$ 450,00 no vencimento. Quanto ele pagou de juros?', array['R$ 22,50', 'R$ 45,00', 'R$ 0,00', 'R$ 450,00']::text[], 2, 'medio', 'Pagar o valor total da fatura até o vencimento evita juros. Nesse caso, o cartão só adiou o pagamento, sem custo extra.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m2', 'cartao-de-credito-1-quiz', 'Uma compra foi feita um dia depois do fechamento da fatura. Em qual fatura ela costuma entrar?', array['Na fatura que acabou de fechar', 'Na fatura seguinte', 'Em nenhuma fatura', 'Só na fatura de seis meses depois']::text[], 1, 'medio', 'Depois do fechamento, as compras entram na fatura do mês seguinte, com novo fechamento e novo vencimento.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m3', 'cartao-de-credito-1-quiz', 'Um cartão tem limite de R$ 3.000,00 e a fatura aberta é de R$ 1.200,00. Se só essa fatura usa o limite, quanto ainda está disponível?', array['R$ 1.800,00', 'R$ 1.200,00', 'R$ 3.000,00', 'R$ 4.200,00']::text[], 0, 'medio', 'O limite disponível é o limite menos o que já foi usado: R$ 3.000,00 − R$ 1.200,00 = R$ 1.800,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-f1', 'cartao-de-credito-2-quiz', 'O que acontece com a parte da fatura que não foi paga?', array['Ela some, porque o banco perdoa a dívida', 'Ela entra no crédito rotativo, com juros altos', 'Ela vira desconto na próxima fatura', 'Ela é paga automaticamente pelo banco']::text[], 1, 'facil', 'O valor não pago entra no rotativo, uma das modalidades de crédito mais caras do mercado. Por isso, o ideal é pagar o valor total da fatura.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m1', 'cartao-de-credito-2-quiz', 'Uma fatura de R$ 600,00 teve pagamento mínimo de R$ 90,00. Quanto vai para o rotativo?', array['R$ 510,00', 'R$ 90,00', 'R$ 600,00', 'R$ 690,00']::text[], 0, 'medio', 'O que não foi pago vai para o rotativo: R$ 600,00 − R$ 90,00 = R$ 510,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m2', 'cartao-de-credito-2-quiz', 'R$ 400,00 ficam no rotativo, a 10% ao mês, por um mês. Quanto a pessoa passa a dever?', array['R$ 400,00', 'R$ 410,00', 'R$ 500,00', 'R$ 440,00']::text[], 3, 'medio', 'Os juros do mês são 10% de R$ 400,00 = R$ 40,00. A dívida passa para R$ 400,00 + R$ 40,00 = R$ 440,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-d1', 'cartao-de-credito-2-quiz', 'Uma fatura de R$ 800,00 teve pagamento mínimo de R$ 100,00 e o rotativo cobra 10% ao mês. Qual saldo será parcelado na fatura seguinte?', array['R$ 700,00', 'R$ 800,00', 'R$ 770,00', 'R$ 880,00']::text[], 2, 'dificil', 'Foram para o rotativo R$ 800,00 − R$ 100,00 = R$ 700,00. Os juros de 10% somam R$ 70,00, e o saldo parcelado é R$ 770,00. Esquecer os juros do rotativo leva ao erro de R$ 700,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-f1', 'cartao-de-credito-3-quiz', 'O que é o CET (custo efetivo total) de uma operação de crédito?', array['O custo total da operação: juros, tarifas e impostos', 'Só a taxa de juros anunciada', 'O limite liberado pelo banco', 'A data de vencimento da parcela']::text[], 0, 'facil', 'O CET reúne tudo o que se paga numa operação de crédito. Comparar o CET é mais seguro do que olhar só a taxa de juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m1', 'cartao-de-credito-3-quiz', 'Pela Lei nº 14.690/2023, qual é o limite para a soma dos juros do rotativo e do parcelamento?', array['Até 10% do valor que ficou em aberto', 'Até 100% do valor que ficou em aberto', 'Até 500% do valor que ficou em aberto', 'Não existe limite']::text[], 1, 'medio', 'A soma dos juros não pode passar de 100% do valor que ficou em aberto. Na prática, o total pago nas parcelas não passa do dobro desse valor.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-d1', 'cartao-de-credito-3-quiz', 'O valor que ficou em aberto foi de R$ 500,00. Pelo teto legal, até quanto a soma das parcelas pode chegar?', array['R$ 500,00', 'R$ 750,00', 'R$ 1.000,00', 'R$ 1.500,00']::text[], 2, 'dificil', 'Os juros podem somar no máximo 100% de R$ 500,00, ou seja, R$ 500,00. Somando ao valor em aberto, as parcelas chegam a, no máximo, R$ 1.000,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-d2', 'cartao-de-credito-3-quiz', 'Um saldo de R$ 1.000,00 foi parcelado em 10 parcelas de R$ 140,00. Quanto foi pago de juros no total?', array['R$ 40,00', 'R$ 140,00', 'R$ 1.400,00', 'R$ 400,00']::text[], 3, 'dificil', 'As parcelas somam 10 × R$ 140,00 = R$ 1.400,00. Os juros são a diferença para o saldo parcelado: R$ 1.400,00 − R$ 1.000,00 = R$ 400,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-f1', 'inflacao-e-investimentos-1-quiz', 'O que é inflação?', array['A queda geral dos preços', 'O aumento do salário de todos os trabalhadores', 'O aumento geral e contínuo dos preços', 'A taxa de juros do cartão de crédito']::text[], 2, 'facil', 'Inflação é o aumento geral e contínuo dos preços. Com ela, a mesma quantia de dinheiro compra menos com o passar do tempo.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m1', 'inflacao-e-investimentos-1-quiz', 'Com inflação de 10% ao ano, um lanche que custa R$ 20,00 hoje passa a custar quanto daqui a um ano, se acompanhar a inflação?', array['R$ 20,10', 'R$ 21,00', 'R$ 30,00', 'R$ 22,00']::text[], 3, 'medio', 'Um aumento de 10% sobre R$ 20,00 dá R$ 2,00. O lanche passa a custar R$ 20,00 + R$ 2,00 = R$ 22,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m2', 'inflacao-e-investimentos-1-quiz', 'Qual índice mede a inflação oficial no Brasil?', array['O IPCA, calculado pelo IBGE', 'O CDI, taxa de referência da renda fixa', 'O CET, calculado por cada banco', 'O limite do cartão de crédito']::text[], 0, 'medio', 'O IPCA, Índice Nacional de Preços ao Consumidor Amplo, é calculado pelo IBGE e é a referência oficial da inflação no Brasil.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m3', 'inflacao-e-investimentos-1-quiz', 'Em um ano em que os preços sobem 6%, o salário de Paula continua o mesmo. O que acontece com o poder de compra dela?', array['Aumenta, porque os preços subiram', 'Diminui, porque o mesmo salário compra menos', 'Fica igual, porque o salário não mudou', 'Dobra, porque o dinheiro vale mais']::text[], 1, 'medio', 'Se os preços sobem e o salário não muda, cada real compra menos. Essa é a perda do poder de compra causada pela inflação.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-f1', 'inflacao-e-investimentos-2-quiz', 'O que é o rendimento real de uma aplicação?', array['O rendimento anunciado, sem descontar nada', 'O valor investido no começo', 'O total de impostos pagos', 'O rendimento depois de descontar a inflação']::text[], 3, 'facil', 'O rendimento real mostra quanto o seu poder de compra cresceu: é o rendimento descontada a inflação do período.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m1', 'inflacao-e-investimentos-2-quiz', 'Uma aplicação rende 9% ao ano e a inflação é de 4% ao ano. Pela conta aproximada (rendimento − inflação), qual é o ganho real?', array['5% ao ano', '4% ao ano', '9% ao ano', '13% ao ano']::text[], 0, 'medio', 'Pela conta aproximada, o ganho real é 9% − 4% = 5% ao ano. A conta exata dá um valor um pouco menor.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m2', 'inflacao-e-investimentos-2-quiz', 'Num ano com inflação de 7%, qual destas aplicações deu ganho real positivo?', array['Uma que rendeu 5%', 'Uma que rendeu 9%', 'Uma que rendeu 7%, igual à inflação', 'Uma que rendeu 3%']::text[], 1, 'medio', 'Só há ganho real quando o rendimento supera a inflação. Com 9% contra 7%, o poder de compra cresce; com 7%, fica igual; com 5% ou 3%, diminui.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-d1', 'inflacao-e-investimentos-2-quiz', 'Uma aplicação rende 10% ao ano e a inflação é de 5% ao ano. Qual é o ganho real pela conta exata, (1 + rendimento) ÷ (1 + inflação) − 1?', array['Exatamente 5% ao ano', 'Cerca de 15,50% ao ano', 'Cerca de 4,76% ao ano', 'Cerca de 2% ao ano']::text[], 2, 'dificil', '(1 + 0,10) ÷ (1 + 0,05) − 1 = 1,10 ÷ 1,05 − 1 ≈ 4,76%. Subtrair 10% − 5% dá 5%, que é só uma aproximação.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-f1', 'inflacao-e-investimentos-3-quiz', 'O que significa diversificar os investimentos?', array['Colocar todo o dinheiro no ativo que mais rende', 'Dividir o dinheiro entre ativos diferentes', 'Vender tudo e guardar o dinheiro em casa', 'Pegar dinheiro emprestado para investir']::text[], 1, 'facil', 'Diversificar é espalhar o dinheiro por ativos diferentes, para que a queda de um deles não derrube tudo.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m1', 'inflacao-e-investimentos-3-quiz', 'Como funciona um fundo de investimento?', array['Reúne o dinheiro de várias pessoas para comprar vários ativos', 'É uma conta que garante lucro todo mês', 'É um empréstimo feito pelo banco ao investidor', 'É um imposto cobrado sobre os ganhos']::text[], 0, 'medio', 'Num fundo, o dinheiro de muitos investidores é reunido e aplicado em vários ativos. Isso facilita a diversificação, mas não elimina o risco.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-d1', 'inflacao-e-investimentos-3-quiz', 'Você divide R$ 2.000,00 em 4 partes iguais. Se uma delas perde 40% e as outras não mudam, quanto você tem no total?', array['R$ 1.200,00', 'R$ 1.500,00', 'R$ 1.600,00', 'R$ 1.800,00']::text[], 3, 'dificil', 'Cada parte tem R$ 500,00. A que perdeu 40% ficou com R$ 300,00. O total é 3 × R$ 500,00 + R$ 300,00 = R$ 1.800,00, uma perda de só R$ 200,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-d2', 'inflacao-e-investimentos-3-quiz', 'Qual afirmação sobre diversificar os investimentos está correta?', array['Elimina totalmente o risco', 'Garante lucro em qualquer cenário', 'Reduz o risco de grandes perdas, mas não o elimina', 'Só funciona para quem tem muito dinheiro']::text[], 2, 'dificil', 'Diversificar espalha o risco, mas todo investimento pode ter perdas. Não há garantia de lucro, e dá para diversificar com valores pequenos, por exemplo em fundos.', true) on conflict (id) do nothing;
